{
  "title": "Brick Compiler & Layer Inspector",
  "width": 920,
  "height": 150,
  "controls": [
    {
      "type": "select",
      "label": "3D Sculpture (SDF)",
      "bind": "brick_model",
      "default": 0,
      "options": [
        {
          "label": "0 · Classic Wooden-Style Duck",
          "value": 0
        },
        {
          "label": "1 · Castle Keep & Battlements",
          "value": 1
        },
        {
          "label": "2 · Hollow Geodesic Dome",
          "value": 2
        },
        {
          "label": "3 · Torus Ring Sculpture",
          "value": 3
        }
      ],
      "x": 12,
      "y": 42,
      "width": 250,
      "height": 64
    },
    {
      "type": "select",
      "label": "Layer Seam Strategy",
      "bind": "brick_stagger",
      "default": 1,
      "options": [
        {
          "label": "Staggered joints (running bond)",
          "value": 1
        },
        {
          "label": "Plain greedy (joints may line up)",
          "value": 0
        }
      ],
      "x": 278,
      "y": 42,
      "width": 230,
      "height": 64
    },
    {
      "type": "select",
      "label": "Core Mode",
      "bind": "brick_hollow",
      "default": 1,
      "options": [
        {
          "label": "Hollow Shell (1-Brick Wall)",
          "value": 1
        },
        {
          "label": "Solid Voxel Core",
          "value": 0
        }
      ],
      "x": 524,
      "y": 42,
      "width": 190,
      "height": 64
    },
    {
      "type": "slider",
      "label": "Live Cut-Plane Layer",
      "bind": "brick_cut_layer",
      "default": 14,
      "min": 1,
      "max": 14,
      "step": 1,
      "x": 730,
      "y": 42,
      "width": 178,
      "height": 64
    }
  ]
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <nb.h>

/* Grid dimensions in studs (X, Z) and brick layers (Y) */
#define GX 16
#define GZ 16
#define GY 14

/* Official LDraw colour codes mapped in our palette:
   1 = Bright Red, 2 = Bright Yellow, 3 = Bright Orange,
   4 = Bright Blue, 5 = Light Bluish Grey, 6 = Dark Bluish Grey, 7 = White */
static int vox[GY][GZ][GX];
static int core_vox[GY][GZ][GX];
static int used[GZ][GX];

struct PartSpec {
  const char *design_id;
  const char *name;
  int w;
  int l;
};

/* Standard brick catalogue ordered by area (greedy preference) */
static const struct PartSpec CATALOGUE[] = {
  { "3001", "Brick 2x4", 2, 4 },
  { "3002", "Brick 2x3", 2, 3 },
  { "3003", "Brick 2x2", 2, 2 },
  { "3010", "Brick 1x4", 1, 4 },
  { "3622", "Brick 1x3", 1, 3 },
  { "3004", "Brick 1x2", 1, 2 },
  { "3005", "Brick 1x1", 1, 1 },
};
#define NUM_PARTS 7

struct PlacedBrick {
  int x, y, z;
  int sx, sz;
  int color;
  int part_idx;
};

static struct PlacedBrick bricks[2048];
static int num_bricks = 0;

/* Evaluate Signed Distance Field / procedural sculpture at (x, y, z)
   accounting for the 5:6 stud-to-brick aspect ratio (dy * 1.2) */
int sample_sculpture(int model, int x, int y, int z) {
  double cx = x - 7.5;
  double cz = z - 7.5;
  double cy = (y - 5.0) * 1.2;

  if (model == 0) {
    /* Classic toy duck: red baseplate pedestal, yellow body/head, orange beak */
    if (y == 0 && fabs(cx) <= 4.5 && fabs(cz) <= 4.5) return 1;
    /* Ellipsoid body */
    double body = (cx * cx) / 30.0 + ((y - 4.2) * (y - 4.2)) / 9.5 + (cz * cz) / 18.0;
    if (body <= 1.0 && y >= 1 && y <= 7) return (y == 4 || y == 5) ? 1 : 2;
    /* Tail */
    if (x <= 3 && x >= 1 && y >= 5 && y <= 7 && fabs(cz) <= 1.6) return 2;
    /* Neck & head */
    double hx = x - 10.2, hz = cz;
    if (hx * hx + hz * hz <= 6.5 && y >= 6 && y <= 11) {
      if (y == 10 && (z == 6 || z == 9) && x >= 10) return 6; /* Eyes */
      return 2;
    }
    /* Orange beak */
    if (x >= 12 && x <= 14 && y >= 8 && y <= 9 && fabs(cz) <= 2.0) return 3;
    return 0;
  } else if (model == 1) {
    /* Castle Keep with corner towers, battlements & arched gate */
    int ax = (int)floor(fabs(cx)), az = (int)floor(fabs(cz));
    /* Corner towers */
    if (ax >= 4 && ax <= 6 && az >= 4 && az <= 6 && y <= 12) {
      if (y == 12 && ((x + z) & 1)) return 0; /* Crenellations */
      return (y == 0) ? 6 : 5;
    }
    /* Curtain walls */
    if ((ax == 5 || az == 5) && ax <= 5 && az <= 5 && y <= 9) {
      if (x >= 12 && fabs(cz) <= 1.5 && y >= 1 && y <= 5) return 0; /* Gate arch */
      if (y == 9 && ((x + z) & 1)) return 0;
      return (y % 3 == 0) ? 6 : 5;
    }
    /* Central spire */
    if (ax <= 2 && az <= 2 && y <= 13) return (y >= 11) ? 1 : 7;
    return 0;
  } else if (model == 2) {
    /* Geodesic Striped Dome */
    double r = sqrt(cx * cx + cy * cy + cz * cz);
    if (y == 0 && r <= 7.4) return 6;
    if (y >= 1 && r <= 7.2 && r >= 4.2) {
      if (fabs(cx) <= 1.5 && z >= 11 && y <= 4) return 0; /* Skylight portal */
      return (y % 3 == 0) ? 4 : 7;
    }
    return 0;
  } else {
    /* Torus Ring Sculpture */
    double major = sqrt(cx * cx + cz * cz) - 4.6;
    double d = major * major + (cy * 0.85) * (cy * 0.85);
    if (d <= 5.2) {
      int band = ((int)floor(atan2(cz, cx) * 2.5 + y)) & 3;
      return (band == 0) ? 1 : (band == 1) ? 2 : (band == 2) ? 4 : 7;
    }
    return 0;
  }
}

int can_fit(int y, int x0, int z0, int sx, int sz, int color) {
  if (x0 + sx > GX || z0 + sz > GZ) return 0;
  for (int dz = 0; dz < sz; dz++) {
    for (int dx = 0; dx < sx; dx++) {
      if (used[z0 + dz][x0 + dx]) return 0;
      if (vox[y][z0 + dz][x0 + dx] != color) return 0;
    }
  }
  return 1;
}

/* Which brick covers each stud, -1 for none; filled in as bricks are placed. */
static int owner[GY][GZ][GX];

/* A joint between two bricks that sits right above a joint in the layer below
   runs straight up the wall: a weak spot. Count how much of a brick's right
   and far edges would do that (its other two edges are already decided). */
int aligned_joints(int y, int x0, int z0, int sx, int sz) {
  if (y == 0) return 0;
  int n = 0, xe = x0 + sx, ze = z0 + sz;
  for (int dz = 0; dz < sz; dz++) {
    int z = z0 + dz;
    if (xe < GX && vox[y][z][xe] && owner[y - 1][z][xe - 1] >= 0 && owner[y - 1][z][xe] >= 0 &&
        owner[y - 1][z][xe - 1] != owner[y - 1][z][xe]) n++;
  }
  for (int dx = 0; dx < sx; dx++) {
    int x = x0 + dx;
    if (ze < GZ && vox[y][ze][x] && owner[y - 1][ze - 1][x] >= 0 && owner[y - 1][ze][x] >= 0 &&
        owner[y - 1][ze - 1][x] != owner[y - 1][ze][x]) n++;
  }
  return n;
}

int main(void) {
  int model = (int)nb_get_int("brick_model", 0);
  int stagger = (int)nb_get_int("brick_stagger", 1);
  int hollow = (int)nb_get_int("brick_hollow", 1);

  int raw_voxels = 0, carved_voxels = 0;
  for (int y = 0; y < GY; y++) {
    for (int z = 0; z < GZ; z++) {
      for (int x = 0; x < GX; x++) {
        core_vox[y][z][x] = sample_sculpture(model, x, y, z);
        vox[y][z][x] = core_vox[y][z][x];
        if (core_vox[y][z][x] > 0) raw_voxels++;
      }
    }
  }

  /* Interior shell carving: erode voxels fully enclosed by 6-neighbours */
  if (hollow) {
    for (int y = 1; y < GY - 1; y++) {
      for (int z = 1; z < GZ - 1; z++) {
        for (int x = 1; x < GX - 1; x++) {
          if (core_vox[y][z][x] > 0 &&
              core_vox[y - 1][z][x] > 0 && core_vox[y + 1][z][x] > 0 &&
              core_vox[y][z - 1][x] > 0 && core_vox[y][z + 1][x] > 0 &&
              core_vox[y][z][x - 1] > 0 && core_vox[y][z][x + 1] > 0) {
            vox[y][z][x] = 0;
            carved_voxels++;
          }
        }
      }
    }
  }

  int part_counts[NUM_PARTS] = {0};
  num_bricks = 0;
  memset(owner, -1, sizeof owner);

  /* Layer-by-layer greedy brick merger */
  for (int y = 0; y < GY; y++) {
    memset(used, 0, sizeof used);
    int flip_axis = stagger ? (y & 1) : 0;

    for (int z = 0; z < GZ; z++) {
      for (int x = 0; x < GX; x++) {
        int col = vox[y][z][x];
        if (col == 0 || used[z][x]) continue;

        /* Plain greedy: the biggest brick that fits. Staggered: turn the
           preferred direction 90 deg each layer, and steer clear of joints
           that line up with the layer below, even if it means a smaller brick. */
        int chosen_p = NUM_PARTS - 1, chosen_sx = 1, chosen_sz = 1, best = -1000;
        for (int p = 0; p < NUM_PARTS; p++) {
          for (int turn = 0; turn < 2; turn++) {
            int w = CATALOGUE[p].w, l = CATALOGUE[p].l;
            int sx = (flip_axis ^ turn) ? l : w;
            int sz = (flip_axis ^ turn) ? w : l;
            if (turn && sx == sz) continue;
            if (!can_fit(y, x, z, sx, sz, col)) continue;
            int score = 4 * sx * sz - (stagger ? 6 * aligned_joints(y, x, z, sx, sz) : 0);
            if (score > best) { best = score; chosen_p = p; chosen_sx = sx; chosen_sz = sz; }
          }
        }

        for (int dz = 0; dz < chosen_sz; dz++)
          for (int dx = 0; dx < chosen_sx; dx++) {
            used[z + dz][x + dx] = 1;
            owner[y][z + dz][x + dx] = num_bricks;
          }

        if (num_bricks < 2048) {
          bricks[num_bricks++] = (struct PlacedBrick){ x, y, z, chosen_sx, chosen_sz, col, chosen_p };
          part_counts[chosen_p]++;
        }
      }
    }
  }

  /* Measure vertical interlocking: how many bricks bridge >= 2 distinct bricks on layer y-1 */
  int upper_bricks = 0, interlocked_bricks = 0;
  for (int i = 0; i < num_bricks; i++) {
    if (bricks[i].y == 0) continue;
    upper_bricks++;
    int first_below = -2, bridged = 0;
    for (int dz = 0; dz < bricks[i].sz; dz++) {
      for (int dx = 0; dx < bricks[i].sx; dx++) {
        int b = owner[bricks[i].y - 1][bricks[i].z + dz][bricks[i].x + dx];
        if (b >= 0) {
          if (first_below == -2) first_below = b;
          else if (b != first_below) bridged = 1;
        }
      }
    }
    if (bridged) interlocked_bricks++;
  }

  double interlock_pct = upper_bricks > 0 ? (100.0 * interlocked_bricks / upper_bricks) : 0.0;
  int active_studs = raw_voxels - carved_voxels;

  printf("=== Brick Compiler & Greedy Mesher ===\n");
  printf("Grid: %dx%d studs x %d layers (5:6 aspect ratio: 8.0mm x 9.6mm)\n", GX, GZ, GY);
  printf("Raw SDF Voxels: %d | Carved Interior: %d | Active Stud Volume: %d\n",
         raw_voxels, carved_voxels, active_studs);
  printf("Merged Bricks:  %d (%.2fx compression vs 1x1 voxels)\n",
         num_bricks, num_bricks > 0 ? (double)active_studs / num_bricks : 1.0);
  printf("Seam Interlock: %.1f%% of upper bricks bridge multiple lower bricks\n\n", interlock_pct);

  printf("%-8s %-14s %8s %10s\n", "Part ID", "Description", "Count", "Studs");
  printf("--------------------------------------------\n");
  for (int p = 0; p < NUM_PARTS; p++) {
    if (part_counts[p] > 0) {
      printf("%-8s %-14s %8d %10d\n",
             CATALOGUE[p].design_id, CATALOGUE[p].name,
             part_counts[p], part_counts[p] * CATALOGUE[p].w * CATALOGUE[p].l);
    }
  }

  /* Serialize compact JSON for Three.js */
  static char json[65536];
  int pos = 0;
  pos += snprintf(json + pos, sizeof(json) - pos,
    "{\"gx\":%d,\"gy\":%d,\"gz\":%d,\"rawVoxels\":%d,\"carvedVoxels\":%d,"
    "\"brickCount\":%d,\"interlockPct\":%.1f,\"bom\":[",
    GX, GY, GZ, raw_voxels, carved_voxels, num_bricks, interlock_pct);
  for (int p = 0; p < NUM_PARTS; p++) {
    pos += snprintf(json + pos, sizeof(json) - pos,
      "%s{\"id\":\"%s\",\"name\":\"%s\",\"count\":%d}",
      p ? "," : "", CATALOGUE[p].design_id, CATALOGUE[p].name, part_counts[p]);
  }
  pos += snprintf(json + pos, sizeof(json) - pos, "],\"bricks\":[");
  for (int i = 0; i < num_bricks; i++) {
    pos += snprintf(json + pos, sizeof(json) - pos,
      "%s[%d,%d,%d,%d,%d,%d]",
      i ? "," : "",
      bricks[i].x, bricks[i].y, bricks[i].z,
      bricks[i].sx, bricks[i].sz, bricks[i].color);
  }
  pos += snprintf(json + pos, sizeof(json) - pos, "]}");
  nb_set_json("brick_build", json);
  return 0;
}
